function keyPress = perfFeedback(str,x,y)global scr visualbounds = Screen(scr.myimg,'TextBounds',str);pt = 0.012*length(str); % presentation timex  = x-bounds(3)/2;     % x positiony  = y-bounds(4)/2;     % y positionc  = visual.fgColor(1); % colorWaitSecs(0.2);nBlank = round(0.20*1/(scr.fd*scr.rate)); % fade out takes 0.2 secsnewFrame = 0;while ~newFrame    % Screen('BlendFunction', scr.myimg, GL_ONE, GL_ZERO);    Screen('FillRect', scr.myimg, visual.bgColor);    Screen('Drawtext', scr.myimg, str,x,y,c);    % DrawFormattedText(scr.myimg, str, x, y, c);    newFrame = PsychProPixx('QueueImage', scr.myimg);endkeyPress = 0;while ~keyPress    keyPress = checkTarPress(1:231);   % accept all buttonsendnewFrame = 0;while ~newFrame    rubber([]);    newFrame = PsychProPixx('QueueImage', scr.myimg);end